#include "../../activity/ContentStore.h"
#include "../../activity/PairAdmission.h"
#include <sodium.h>
#include <iostream>
using namespace private_input::activity;
GroupIdentity identity(){GroupIdentity i;i.device=newId();i.owner=newId();randombytes_buf(i.signingSeed.data(),32);randombytes_buf(i.ownerSeed.data(),32);randombytes_buf(i.exchangeSecret.data(),32);return i;}
Json compact(Json bundle){for(auto&p:bundle["packages"].items)p.fields.erase("membership");bundle["challenge"]["template"].fields.erase("membership");return bundle;}
Json ticket(const GroupIdentity&i,const Json&m,uint64_t now){Key secret;randombytes_buf(secret.data(),32);auto hash=sha256(Data(secret.begin(),secret.end()));return signedEnvelope(parseId(m.at("group").str()),i.device,i.signingSeed,8,Json::object({{"ticket",uuidText(newId())},{"secretHash",base64(Data(hash.begin(),hash.end()))},{"expiresAt",now+290},{"invitation",Json::object({{"version",1},{"endpoint","https://relay.example.invalid"},{"anchor",Json::object({{"group",m.at("group")},{"ownerID",m.at("ownerID")},{"ownerPublic",m.at("ownerPublic")}})}})}}),now,false);}
int main(){if(sodium_init()<0)return 1;auto a=identity(),b=identity(),c=identity();auto now=unixTime();auto initial=initialMembership(a),firstRequest=pairRequest(b,now),secondRequest=pairRequest(c,now);auto first=prepareAdmission(initial,a,firstRequest,now);auto second=prepareAdmission(first.bundle.at("membership"),b,secondRequest,now);auto m=anchorOf(initial).verify(private_input::protocol::decodeMembershipJSON(second.bundle.at("membership").dump()));ContentStore store({},[](const Json&){});store.configure(m.anchor().group,m.statement().epoch,true,true);store.record("ni hao","你好",uuidText(c.device));store.publishLearning(m,c,second.localKey,now);store.sendText("Windows shared text fixture",m,c,second.localKey,now);auto pull=signedEnvelope(m.anchor().group,a.device,a.signingSeed,2,Json::object({{"limit",2},{"domains",3}}),now,false);std::vector<Json>events=store.pending(now),ids;for(const auto&e:events)ids.push_back(e.at("event"));auto ack=signedEnvelope(m.anchor().group,a.device,a.signingSeed,3,Json::object({{"events",Json::array(ids)}}),now,false);auto result=Json::object({{"now",now},{"initial",initial},{"firstRequest",firstRequest},{"firstAdmission",compact(first.bundle)},{"firstTicket",ticket(a,initial,now)},{"secondRequest",secondRequest},{"secondAdmission",compact(second.bundle)},{"secondTicket",ticket(b,first.bundle.at("membership"),now)},{"events",Json::array(events)},{"pull",pull},{"ack",ack}});std::cout<<result.dump()<<'\n';}
